package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.time.LocalDate;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * An invoice raised on a project: an amount, and the id of the project it bills. Persisted to the
 * {@code invoices} table (Flyway V4). The id is database-generated (IDENTITY) on create; the seed
 * path inserts explicit ids directly via JdbcTemplate (see {@link TestSupportController}).
 */
@Entity
@Table(name = "invoices")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "project_id")
    private Long projectId;

    private BigDecimal amount;

    /**
     * Percentage taken off the subtotal as a discount (Flyway V27), 0-100. Defaults to zero, so an
     * invoice with no discount set bills its full subtotal. The final total is worked out from this
     * and the amount on the server (see {@link InvoiceSummaryGetLogic}), never typed.
     */
    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    /** Lifecycle status: DRAFT (default, matching Flyway V9) -> SENT (once sent) -> PAID (once paid). */
    private String status = "DRAFT";

    /** The date the invoice went out (Flyway V7). Serialized as an ISO date, e.g. "2026-01-05". */
    @Column(name = "issued_date")
    private LocalDate issuedDate;

    /** The date the invoice is due (Flyway V7). Serialized as an ISO date, e.g. "2026-02-04". */
    @Column(name = "due_date")
    private LocalDate dueDate;

    public Invoice() {
    }

    public Invoice(Long projectId, BigDecimal amount) {
        this.projectId = projectId;
        this.amount = amount;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public void setProjectId(Long projectId) {
        this.projectId = projectId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    public void setDiscountPct(BigDecimal discountPct) {
        this.discountPct = discountPct;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public void setIssuedDate(LocalDate issuedDate) {
        this.issuedDate = issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public void setDueDate(LocalDate dueDate) {
        this.dueDate = dueDate;
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * The one place the invoice discount money-rule lives: given an invoice's subtotal (the worked-out
 * sum of its line items, kept in the amount column) and its percentage discount (Flyway V27), works
 * out the discount in money and the net total actually billed (subtotal less that discount). Kept in
 * one place so every surface that shows "what is owed" — the invoice detail, the client statement
 * and the home dashboard — discounts the same way, with the same whole-cent rounding.
 */
public final class InvoiceMoney {

    private InvoiceMoney() {
    }

    /** The discount in money: the subtotal times the percentage, rounded to whole cents. Null-safe. */
    public static BigDecimal discount(BigDecimal subtotal, BigDecimal discountPct) {
        BigDecimal base = subtotal != null ? subtotal : BigDecimal.ZERO;
        BigDecimal pct = discountPct != null ? discountPct : BigDecimal.ZERO;
        return base.multiply(pct)
                .divide(BigDecimal.valueOf(100))
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** The net total billed: the subtotal less the discount. Null-safe. */
    public static BigDecimal netTotal(BigDecimal subtotal, BigDecimal discountPct) {
        BigDecimal base = subtotal != null ? subtotal : BigDecimal.ZERO;
        return base.subtract(discount(base, discountPct));
    }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import org.springframework.web.bind.annotation.RequestParam;
import net.officefloor.web.ObjectResponse;

/**
 * {@code GET /api/invoices/summary?invoiceId=<id>} — the money breakdown for one invoice: its
 * subtotal (the worked-out sum of its line items, Flyway V13/V14, kept in the amount column), the
 * percentage discount taken off it (Flyway V27), the discount in money, and the final total
 * (subtotal minus discount). The figures are worked out on the server so the money math lives in one
 * place; an invoice with no discount simply bills its full subtotal. Wired by
 * {@code officefloor/rest/api/invoices/summary.GET.yml}.
 */
public class InvoiceSummaryGetLogic {

    public void service(@RequestParam("invoiceId") Long invoiceId, InvoiceRepository invoices,
            ObjectResponse<InvoiceSummaryView> response) {
        Invoice invoice = invoices.findById(invoiceId).orElse(null);
        BigDecimal subtotal = invoice != null ? invoice.getAmount() : BigDecimal.ZERO;
        BigDecimal discountPct = invoice != null && invoice.getDiscountPct() != null
                ? invoice.getDiscountPct()
                : BigDecimal.ZERO;
        // Discount in money, rounded to whole cents; the final total is the subtotal less that.
        // The same one-place rule the dashboard, statement and due figures use (see InvoiceMoney).
        BigDecimal discount = InvoiceMoney.discount(subtotal, discountPct);
        BigDecimal total = subtotal.subtract(discount);
        response.send(new InvoiceSummaryView(invoiceId, subtotal, discountPct, discount, total));
    }

    /** One invoice's money breakdown: subtotal, the discount percentage, the discount, the total. */
    public static class InvoiceSummaryView {
        private final long invoiceId;
        private final BigDecimal subtotal;
        private final BigDecimal discountPct;
        private final BigDecimal discount;
        private final BigDecimal total;

        public InvoiceSummaryView(long invoiceId, BigDecimal subtotal, BigDecimal discountPct,
                BigDecimal discount, BigDecimal total) {
            this.invoiceId = invoiceId;
            this.subtotal = subtotal;
            this.discountPct = discountPct;
            this.discount = discount;
            this.total = total;
        }

        public long getInvoiceId() {
            return invoiceId;
        }

        public BigDecimal getSubtotal() {
            return subtotal;
        }

        public BigDecimal getDiscountPct() {
            return discountPct;
        }

        public BigDecimal getDiscount() {
            return discount;
        }

        public BigDecimal getTotal() {
            return total;
        }
    }
}

